for label, sub in [('incident', df[(df.bucket_start_s>=secs('17:14:06')) & (df.bucket_start_s<secs('17:15:58'))]), ('baseline', df[(df.bucket_start_s>=secs('17:13:05')) & (df.bucket_start_s<secs('17:14:06'))])]:
